/*
 * wifi_pwd_error_img.c
 * ta_1 输入框的“密码错误”提示图（214x55，与 SettingsPage2Wireless2_ta_1 同尺寸同位）。
 *
 * 为什么用图片而不是 label：
 *   当前 GUI Guider 导出的 simsun 字库只包含实际用到的少量汉字，
 *   lv_font_simsun_18/20/21/23 均没有“错”(U+9519) / “误”(U+8BEF) 的字形，
 *   直接用 label 显示“密码错误”会出现两个占位方框。
 *   这里把整块输入框外观（页面底色 + 浅红底 + 红边框 + 红字）预渲染成 RGB565 位图，
 *   显示时覆盖在 ta_1 上，隐藏时还原正常输入框外观。
 *
 * 重新生成：用 PIL 从 C:/Windows/Fonts/simsun.ttc 20px 渲染，
 *   尺寸 214x55、圆角 12、底色 #FFF1F0、边框 #FF4D4F、文字 #D32F2F，
 *   圆角外区域烘焙为页面底色 #EBEEF5。
 */

